const TOUR = [
 {"t": "Meet the NerdQAxe+", "side": "iso", "refs": [], "flows": [], "cool": false, "p": ["The NerdQAxe+ is the NerdQAxe++'s predecessor: four BM1368 ASICs, the chip of the Bitaxe Supra, on a 12 V board. At the 490 MHz default it hashes at about 2.5 TH/s.", "Everything here comes from the published KiCad files (rev 5.0). The top side carries the ASICs, the two-phase power stage and the plug-in controller; the bottom side carries the decoupling under each chip."]},
 {"t": "12 V comes in", "side": "top", "refs": ["J1", "F1", "D1", "C92"], "flows": ["core"], "p": ["J1 is a 5.5 mm barrel jack marked +12V/5A. Power passes the 5 A fuse F1, and the SMBJ12A TVS diode D1 clamps spikes across the rail.", "A 220 µF capacitor (C92) and a bank of 22 µF ceramics hold the 12 V steady for the power stages next to them."]},
 {"t": "Two phases make VDD", "side": "top", "refs": ["U3", "U4", "U5", "L1", "L2", "C21", "C24", "C86", "C90"], "flows": ["core"], "p": ["U3, a TI TPS53647, controls two CSD95472 smart power stages (U4, U5). Each switches 12 V into its own 220 nH inductor; the ++ adds a third phase to feed its hungrier BM1370s.", "The phases run out of step, so their ripple partly cancels in the 330 µF and 100 µF output capacitors. The result is VDD, about 1.25 V, shared by all four ASICs. In KiCad this net is named +1V2."]},
 {"t": "Talking PMBus to U3", "side": "top", "refs": ["U3", "R36", "R12", "R13", "R1", "R2"], "flows": ["i2c"], "p": ["The ESP32 programs U3 over PMBus at address 0x71: the core voltage, and limits of 30 A per phase. It reads back input voltage, current and temperature for the dashboard.", "U3 starts only when the ESP32 raises PWR_EN (GPIO10, through jumper JP2), and it signals VR_RDY on GPIO11. R1/R2 strap its address and rise time."]},
 {"t": "Support rails: 5 V, 3.3 V, 1.8 V, 0.8 V", "side": "top", "refs": ["U6", "L3", "D2", "D3", "U36", "U7", "TP3"], "flows": ["rails"], "p": ["U6, a small AP3211 buck, makes 5 V from 12 V for the power stages' drivers and, through D3, for the controller module. The module's own regulator makes 3.3 V for the logic.", "U36 and U7 are LDOs that make the ASICs' 1.8 V and 0.8 V I/O rails from 3.3 V. They share an enable line (LDO_EN, GPIO13), so the firmware brings up the I/O rails first, then the core voltage, then releases reset."]},
 {"t": "Four BM1368s in a chain", "side": "top", "refs": ["U19", "U25", "U20", "U26"], "flows": ["chain"], "p": ["The four chips sit in a 2 × 2 block, all on the same VDD rail. Data runs as a daisy chain: the ESP32 talks only to U19, which forwards everything to U25, then U20, then U26. Results travel back the same way.", "Each BM1368 has 1276 small cores, so hashrate ≈ 490 MHz × 1276 × 4 ≈ 2.5 TH/s. Open any ASIC in the inspector for the calculator and pinout."]},
 {"t": "Under the chips", "side": "bottom", "refs": ["C35", "C42", "C50", "C56", "C62", "C66", "C69", "C71", "C93"], "flows": [], "p": ["The bottom side under each ASIC is packed with capacitors. 100 µF, 10 µF and 1 µF parts decouple VDD where the current enters the chips.", "The 1 µF ladders bridge the BM1368's internal domain taps (VDD → tap 3 → tap 2 → tap 1 → GND). Neighbouring chips share tap nets, so one ladder spans two chips."]},
 {"t": "A 25 MHz heartbeat", "side": "bottom", "refs": ["U8", "C25"], "flows": ["clk"], "p": ["U8 is a 25 MHz oscillator on the bottom, just beside U19. Only U19 gets the reference clock; each chip forwards it to the next on CLKO.", "Each chip's PLL multiplies the reference up: 490 MHz is 19.6 × 25 MHz."]},
 {"t": "The controller: T-Display-S3", "side": "top", "refs": ["U30"], "flows": [], "p": ["U30 is a LilyGO T-Display-S3: an ESP32-S3 with a 1.9\" colour screen, plugged in on two 12-pin headers. It runs the NerdQAxe+ fork of ESP-Miner and serves AxeOS.", "It turns pool jobs into work for the chain, checks returned nonces, and runs the voltage, fan and temperature control loops."]},
 {"t": "Crossing voltage domains: U35", "side": "top", "refs": ["U35", "C82", "C83"], "flows": ["uart"], "p": ["The ESP32 uses 3.3 V logic and the ASICs' I/O runs at 1.8 V. U35, a TXU0304, translates TX → CI, RESET → RST_N and RO → RX."]},
 {"t": "Sensors and fans", "side": "top", "refs": ["U37", "U32", "U33", "M1", "M2", "R33", "R35"], "flows": ["thermal"], "p": ["The BM1368s' temperature-diode pins are not wired here. Two TMP1075 sensors read the board temperature instead: U37 beside the ASICs and U38 under the power stage.", "U32, an EMC2302, drives two 12 V PWM fans on M1 and M2 and counts their RPM. U33 shifts its PWM up to 5 V. The firmware runs a PID loop toward a 55 °C ASIC target and 65 °C for the regulator."]},
 {"t": "Heatsink and fan stack", "side": "iso", "refs": ["U19", "U25", "U20", "U26"], "flows": [], "cool": true, "explode": true, "p": ["All four chips share one heatsink, screwed down through the M3 holes on a 75 mm square around them, with a fan on top. The view is exploded so you can see the layers.", "The heatsink and fan here are generic stand-ins sized to the hole pattern, not a specific product."]},
 {"t": "The full mining loop", "side": "iso", "refs": ["U30", "U35", "U19", "U25", "U20", "U26", "U3", "U32"], "flows": ["core", "uart", "chain", "i2c", "thermal", "clk"], "p": ["Everything together: the pool sends a job over Wi-Fi, the ESP32 sends work down the UART to U19, and the chain spreads it across all four chips. Nonces come back up the chain and the ESP32 submits shares.", "Meanwhile U3 and its two power stages hold VDD, U8 clocks the chain, and U32 sets the fans from the sensors. Switch to Free mode to explore any part on your own."]}
];
